{
    "title": "未明档案：红印封存夜",
    "logline": "东方都市深夜，闭馆停电的档案馆封存区，十二人涉入六天推理局，狼人阵营取胜。",
    "acts": [
        {
            "title": "寒夜启局",
            "summary": "冷雨裹着停电夜，十二人困守封存区开推理，首两日夜数人出局，疑云初起。"
        },
        {
            "title": "旧档迷踪",
            "summary": "带红印的封存旧档线索交错，推理进入拉锯期，后续两日夜再有人出局。"
        },
        {
            "title": "终局定音",
            "summary": "猎人触发开枪环节，最后一轮投票结束后，第六天狼人阵营拿下最终胜利。"
        }
    ]
}

